    def f(string, match, base=base):
        if string[0] == '-':
            sign = -1
        else:
            sign = 1

        # Auto-detect base if base is 0 or not specified
        if base == 0 and string[0] == '0' and len(string) > 2:
            if string[1] in 'bB':
                base = 2
            elif string[1] in 'oO':
                base = 8
            elif string[1] in 'xX':
                base = 16
            else:
                base = 10  # default to decimal
        elif base == 0:
            base = 10  # no prefix means decimal

        chars = CHARS[:base]
        string = re.sub('[^%s]' % chars, '', string.lower())
        return sign * int(string, base)
